// --- Animation for view transitions ---
const _origAnimate = animate;
// We hook into the render loop by adding our own update before render
// Since we can't override animate, we use a different approach:
// We'll update in a requestAnimationFrame that runs alongside

let _viewAnimActive = false;

function animateView() {
  const lerp = 0.06;
  let needsUpdate = false;

  if (Math.abs(currentElevation - targetElevation) > 0.1 ||
      Math.abs(currentAzimuth - targetAzimuth) > 0.1 ||
      Math.abs(currentOpacity3D - targetOpacity3D) > 0.005) {
    currentElevation += (targetElevation - currentElevation) * lerp;
    currentAzimuth += (targetAzimuth - currentAzimuth) * lerp;
    currentOpacity3D += (targetOpacity3D - currentOpacity3D) * lerp;
    needsUpdate = true;
  }

  if (needsUpdate) {
    // Update face opacities
    slantedFace.material.opacity = currentOpacity3D;
    xzFace.material.opacity = currentOpacity3D;
    yzFace.material.opacity = currentOpacity3D;

    // Update camera position for view transition
    const azRad = THREE.MathUtils.degToRad(currentAzimuth);
    const elRad = THREE.MathUtils.degToRad(currentElevation);
    const radius = 8;
    const pos = new THREE.Vector3(
      Math.cos(azRad) * Math.cos(elRad) * radius,
      Math.sin(elRad) * radius,
      Math.sin(azRad) * Math.cos(elRad) * radius
    );
    camera.position.copy(pos);
    camera.lookAt(0.3, 0.7, 1.2);
    controls.target.set(0.3, 0.7, 1.2);
    camera.updateProjectionMatrix();
    controls.update();
  }

  requestAnimationFrame(animateView);
}
