// ── dynamic strip / curtain / cross-section (3D) + 2D strip ──
let stripX=0.5;
const stripLine=makeLine(sO,sO,RED);
const strip2D=makeLine(P2(0,0),P2(0,0),RED);
const crossLine=makeLine(sO,sO,ORANGE);
