  new THREE.MeshBasicMaterial({color:RED,transparent:true,opacity:0.3,side:THREE.DoubleSide,depthWrite:false}));
scene.add(curtainMesh);

function updateStrip(x0){
  stripX=x0;
  const yT=2-2*x0, zT=4-4*x0;
  stripLine.geometry.dispose();
  stripLine.geometry=new THREE.BufferGeometry().setFromPoints([S(x0,0,0),S(x0,yT,0)]);
  crossLine.geometry.dispose();
  crossLine.geometry=new THREE.BufferGeometry().setFromPoints([S(x0,0,zT),S(x0,yT,0)]);
  const cg=new THREE.BufferGeometry();
  const p0=S(x0,0,0),p1=S(x0,yT,0),p2=S(x0,0,zT);
  cg.setAttribute('position',new THREE.BufferAttribute(new Float32Array([p0.x,p0.y,p0.z,p1.x,p1.y,p1.z,p2.x,p2.y,p2.z]),3));
  cg.computeVertexNormals(); curtainMesh.geometry.dispose(); curtainMesh.geometry=cg;
  strip2D.geometry.dispose();
  strip2D.geometry=new THREE.BufferGeometry().setFromPoints([P2(x0,0),P2(x0,yT)]);
}
updateStrip(0.5);

