let sweeping=false,sweepDir=1,flash2D=0;
function sweepLoop(){
  if(sweeping){
    stripX+=0.008*sweepDir;
    if(stripX>=1){stripX=1;sweepDir=-1;} if(stripX<=0){stripX=0;sweepDir=1;}
    stripSlider.value=stripX; stripValSpan.textContent=stripX.toFixed(2); updateStrip(stripX);
  }
  if(flash2D>0){flash2D--; baseR2D.material.opacity=0.5+0.4*Math.abs(Math.sin(flash2D*0.25)); if(flash2D===0)baseR2D.material.opacity=0.8;}
  requestAnimationFrame(sweepLoop);
}
